<!doctype html>
<html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CAIXA Loterias | Homologação de Iniciativas</title><link rel="stylesheet" href="/assets/css/styles.css"><script src="/assets/js/dataStore.js" defer></script><script src="/assets/js/databaseService.js" defer></script><script src="/assets/js/auth.js" defer></script><script src="/assets/js/action-feedback.js" defer></script><script src="/assets/js/iniciativas.js" defer></script><script src="/assets/js/app.js" defer></script></head>
<body data-page="iniciativasHomologacao"><div class="app-shell"><header id="appHeader" class="topbar"></header><nav id="appNav" class="sidebar"></nav><main class="content"><section class="page-heading"><p class="eyebrow">Validação da diretoria</p><h1>Homologação de Iniciativas</h1><p>Análise independente dos acompanhamentos enviados.</p></section><nav class="module-tabs"><a href="/homologacoes">Indicadores</a><a class="active" href="/iniciativas/homologacao">Iniciativas</a></nav>
<section class="panel"><div id="initiativeApprovalMessage" class="action-feedback" hidden></div><div class="table-wrap"><table><thead><tr><th>Pilar</th><th>Código</th><th>Iniciativa</th><th>Unidade</th><th>Período</th><th>Status</th><th>Data de envio</th><th>Ação</th></tr></thead><tbody id="initiativeApprovalTable"></tbody></table></div></section>
<section id="initiativeApprovalPanel" class="panel detail-panel" hidden><div class="detail-header"><div><p class="eyebrow">Análise da diretoria</p><h2 id="initiativeApprovalTitle"></h2></div><span id="initiativeApprovalStatus" class="badge info"></span></div><div id="initiativeApprovalSnapshot" class="detail-grid"></div><section><h3>Andamento da Unidade</h3><p id="initiativeApprovalProgress" class="preserve-lines"></p></section><section><h3>Itens do acompanhamento</h3><div id="initiativeApprovalItems"></div></section><section><h3>Evidências</h3><p id="initiativeApprovalReference"></p><div id="initiativeApprovalEvidence" class="evidence-list"></div></section><section><h3>Histórico</h3><div id="initiativeApprovalHistory" class="history-list"></div></section><label class="full-span">Justificativa para devolução/reabertura<textarea id="initiativeApprovalReason" rows="3"></textarea></label><div class="form-actions"><button id="initiativeApproveButton" class="primary-action" type="button">Homologar</button><button id="initiativeReturnButton" class="secondary-action" type="button">Devolver para ajuste</button><button id="initiativeReopenButton" class="secondary-action" type="button">Reabrir para edição</button><button class="secondary-action" type="button" data-close-panel="initiativeApprovalPanel">Voltar</button></div></section>
</main></div></body></html>
